using System;
class VisionChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){var v=new VisionState();Check(v.BaseLight==0&&v.Range(true,0)==0&&v.Range(false,0)==0,"bright with no innate darkvision by default");Check(v.Quality(0,0,10,0,0,0)==0,"bright visible");v.BaseLight=1;Check(v.Quality(0,0,10,0,0,0)==1&&v.Quality(0,0,10,0,30,0)==0,"dim vs darkvision");v.BaseLight=2;Check(v.Quality(0,0,10,0,0,0)==2&&v.Quality(0,0,10,0,30,0)==1&&v.Quality(0,0,35,0,30,0)==2,"dark vision distance and gray dim visibility");v.PlayerRange=180;v.GrantDarkvision(true,10);Check(v.Range(true,10)==180&&v.Range(false,10)==0,"spell preserves longer sense and correct target");v.PlayerRange=0;Check(v.Range(true,4809)==150&&v.Range(true,4810)==0,"eight hour expiry");v.ClearEffects();v.BaseLight=0;v.AddZone(true,20,0,2,0);Check(v.Quality(0,0,40,0,150,0)==2,"darkness blocks line through area even both creatures outside");Check(v.Quality(0,20,40,20,0,0)==0,"line avoiding sphere is clear");Check(v.Quality(20,0,20,0,150,0)==2,"inside darkness");Check(v.Quality(0,0,10,0,0,0,10)==0,"blindsight penetrates darkness");v.AddZone(false,100,0,3,0);Check(!v.HasDarkness(0)&&v.Light(100,0,0)==0,"daylight dispels overlapping low-level darkness");v.AddZone(true,100,0,3,0);Check(!v.HasDarkness(0),"existing daylight dispels new eligible darkness");v.ClearEffects();v.BaseLight=2;v.AddZone(false,0,0,3,10);Check(v.Light(60,0,10)==0&&v.Light(65,0,10)==1&&v.Light(121,0,10)==2,"daylight bright and dim radii");Check(v.Quality(125,0,0,0,0,10)==0,"observer in normal darkness sees illuminated target");Check(v.Light(0,0,610)==2,"daylight expiry");v.ClearEffects();v.BaseLight=0;v.AddZone(true,0,0,4,0);v.AddZone(false,0,0,3,0);Check(v.HasDarkness(0)&&v.Quality(-20,0,20,0,0,0)==0,"magical daylight illuminates higher darkness without dispelling spell");v.EndDarkness();Check(!v.HasDarkness(0)&&v.Zones.Count==1,"ending concentration preserves nonconcentration light");v.ClearEffects();v.AddZone(true,0,0,2,0);Check(v.HasDarkness(99)&&!v.HasDarkness(100),"darkness ten minute expiry");v.GrantDarkvision(false,0);v.ClearEffects();Check(v.Range(false,0)==0&&v.BaseLight==0,"reset effects retains configuration");Check(Math.Abs(VisionState.ReachExit(0,0,4,0,1,0,0,1,5)-.2749995)<.00001,"opportunity visibility uses exit point rather than movement start");Check(VisionState.ReachExit(0,5,4,5,1,0,0,1,5)<0,"path never enters reach");v.ClearEffects();v.AddFog(20,0,1,0);Check(v.FogAt(0,0,0)&&!v.FogAt(-1,0,0),"fog radius boundary");Check(v.Quality(-5,0,45,0,150,0)==2,"fog blocks darkvision through cloud with both endpoints outside");v.AddZone(false,20,0,9,0);Check(v.FogAt(20,0,0)&&v.Quality(0,0,40,0,150,0)==2,"daylight does not dispel or reveal through fog");Check(v.Quality(0,0,10,0,0,0,10)==0,"blindsight still perceives fog target");v.EndDarkness();Check(v.FogAt(20,0,0),"ending darkness alone does not clear fog");v.EndFog();Check(!v.FogAt(20,0,0)&&v.Zones.Count==1,"ending fog preserves daylight");v.ClearEffects();v.AddFog(0,0,3,10);Check(v.FogAt(60,0,10)&&!v.FogAt(61,0,10),"fog upcast radius");Check(!v.FogAt(0,0,610),"fog hour expiry");Console.WriteLine("PASS: lighting, darkvision, exact darkness intersections, daylight overlap and dispelling, concentration, duration, reset and blindsight");}
}
